void aStage::setFsmEvent(bool sleep) {
    if (mbFsmEvent == sleep) {
        return;
    }
    if (scePthreadMutexLock(&mCs.mCSection) != 0) {
        abort();
    }
    if (sleep) {
        sScenario::getInstance()->evEventStart();
    } else {
        sScenario::getInstance()->evEventFinish();
    }
    mbFsmEvent = sleep;
    if (scePthreadMutexUnlock(&mCs.mCSection) != 0) {
        abort();
    }
}

